public class Calculator { public static int addNumbers(int a, int b) { return a + b; } public static int subtractNumbers(int a, int b) { return a - b; } public static int multiplyNumbers(int a, int b) { return a * b; } public static double divideNumbers(int a, int b) { if (b != 0) { return (double) a / b; } else { System.out.println("Cannot divide by zero"); return Double.NaN; } } public static void main(String[] args) { int x = 10; int y = 5; System.out.println(addNumbers(x, y)); System.out.println(subtractNumbers(x, y)); System.out.println(multiplyNumbers(x, y)); System.out.println(divideNumbers(x, y)); } }
